SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:The_Narrow_Margin dbr:A_Pistol_for_Ringo }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}

SELECT ?youngerFilm ?youngerFilmLabel ?youngerDirector ?youngerDirectorLabel ?youngerBirthDate WHERE {
  VALUES (?f1 ?f2) {(dbr:The_Narrow_Margin dbr:A_Pistol_for_Ringo)}
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .
  OPTIONAL { ?d1 dbo:birthDate ?b1 }
  OPTIONAL { ?d2 dbo:birthDate ?b2 }
  OPTIONAL { ?f1 rdfs:label ?f1Label FILTER(lang(?f1Label) = "en") }
  OPTIONAL { ?f2 rdfs:label ?f2Label FILTER(lang(?f2Label) = "en") }
  OPTIONAL { ?d1 rdfs:label ?d1Label FILTER(lang(?d1Label) = "en") }
  OPTIONAL { ?d2 rdfs:label ?d2Label FILTER(lang(?d2Label) = "en") }

  {
    FILTER(bound(?b1) && bound(?b2) && ?b1 < ?b2)
    BIND(?f2 AS ?youngerFilm)
    BIND(?d2 AS ?youngerDirector)
    BIND(?b2 AS ?youngerBirthDate)
    BIND(?d2Label AS ?youngerDirectorLabel)
    BIND(?f2Label AS ?youngerFilmLabel)
  }
  UNION
  {
    FILTER(bound(?b1) && bound(?b2) && ?b2 < ?b1)
    BIND(?f1 AS ?youngerFilm)
    BIND(?d1 AS ?youngerDirector)
    BIND(?b1 AS ?youngerBirthDate)
    BIND(?d1Label AS ?youngerDirectorLabel)
    BIND(?f1Label AS ?youngerFilmLabel)
  }
}

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:The_Narrow_Margin dbr:A_Pistol_for_Ringo }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = "en") }
}
ORDER BY DESC(?birthDate)
LIMIT 1

